export async function mountCandidateClickPicker({source,items,checks,host,valid}){
 const wrapper=document.createElement('section');wrapper.id='instanceClickPicker';const title=document.createElement('p');title.textContent='사진의 물체를 클릭해 후보를 선택하세요. 후보가 겹치면 목록에서 직접 고를 수 있습니다.';const canvas=document.createElement('canvas');canvas.setAttribute('aria-label','사진을 클릭해 물체 후보 선택');canvas.style.cssText='display:block;max-width:100%;max-height:480px;width:auto;height:auto;cursor:crosshair';const message=document.createElement('p');message.setAttribute('role','status');const choices=document.createElement('div');wrapper.append(title,canvas,message,choices);host.before(wrapper);
 const decode=async src=>{const im=new Image();im.src=src;await im.decode();return im;};const original=await decode(source);if(!valid()){wrapper.remove();return null;}const scale=Math.min(1,640/Math.max(original.naturalWidth,original.naturalHeight));canvas.width=Math.max(1,Math.round(original.naturalWidth*scale));canvas.height=Math.max(1,Math.round(original.naturalHeight*scale));const w=canvas.width,h=canvas.height,ctx=canvas.getContext('2d'),masks=[];
 for(const item of items){const url=URL.createObjectURL(item.file);try{const im=await decode(url);if(im.naturalWidth!==original.naturalWidth||im.naturalHeight!==original.naturalHeight)throw Error('후보와 원본 사진의 크기가 다릅니다.');const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(im,0,0,w,h);const data=x.getImageData(0,0,w,h),alpha=new Uint8Array(w*h);let area=0;for(let i=0;i<alpha.length;i++){const a=data.data[i*4+3];alpha[i]=a>24?1:0;if(alpha[i])area++;}x.globalCompositeOperation='source-in';x.fillStyle='#6d43e9';x.fillRect(0,0,w,h);masks.push({alpha,area,overlay:c});}finally{URL.revokeObjectURL(url);}}
 if(!valid()){wrapper.remove();return null;}function draw(){ctx.clearRect(0,0,w,h);ctx.drawImage(original,0,0,w,h);ctx.globalAlpha=.32;for(let i=0;i<masks.length;i++)if(checks[i].checked)ctx.drawImage(masks[i].overlay,0,0);ctx.globalAlpha=1;}
 function choose(i){if(!valid()){message.textContent='원본이 바뀌었습니다. 다시 분석해 주세요.';return;}checks[i].checked=!checks[i].checked;checks[i].dispatchEvent(new Event('change',{bubbles:true}));message.textContent=items[i].name+(checks[i].checked?' 후보 선택':' 후보 선택 해제');choices.replaceChildren();draw();}
 checks.forEach(check=>check.addEventListener('change',draw));canvas.onclick=e=>{if(!valid()){message.textContent='원본이 바뀌었습니다. 다시 분석해 주세요.';return;}const r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)*w/r.width),y=Math.floor((e.clientY-r.top)*h/r.height);if(x<0||y<0||x>=w||y>=h)return;const hit=masks.map((m,i)=>m.alpha[y*w+x]?i:-1).filter(i=>i>=0);choices.replaceChildren();if(!hit.length){message.textContent='이 위치에 분석된 후보가 없습니다. 후보 목록을 확인하거나 다시 분석하세요.';return;}if(hit.length===1){choose(hit[0]);return;}message.textContent='이 위치에 후보가 겹칩니다. 선택할 후보를 직접 고르세요.';for(const i of hit){const b=document.createElement('button');b.type='button';b.className='doc-btn';b.textContent=items[i].name+(checks[i].checked?' · 선택됨':'');b.onclick=()=>choose(i);choices.append(b);}};
 draw();return {element:wrapper};
}
